    ///         shared `openTime` / `lastEmissionUpdate` anchors. Idempotent — re-calls
    ///         silently no-op so a malformed deploy can't accidentally restart decay.
    function notifyTradingOpened(uint64 _openTime) external onlyLBP {
        if (tradingOpened) return;
        tradingOpened = true;
        openTime = _openTime;
        lastEmissionUpdate = _openTime;
        // High-5 fix: anchor `lastTickRLbp` to current pair reserve at open
        // so the FIRST emission tick uses a real (un-manipulable-by-attacker
        // pre-open due to pre-open transfer restrictions) value.
        (, uint112 r1, ) = pair.getReserves();
        lastTickRLbp = r1;
    }

    /// @notice Called by LBP at every Layer 7a/8 to materialize a user's pending rewards.
    ///         `_harvest` self-ticks emission internally — the up-to-date accumulator
    ///         is read inside the harvest body.
    function notifyHarvest(address user) external onlyLBP nonReentrant {
        _harvest(user);
    }

