            uint256 nodeDelta = accNode - userNodeIndex[user];
            if (nodeDelta > 0) {
                uint256 nodeReward = nodeDelta / 1e18;
                if (nodeReward > 0) {
                    lbp.mintReward(user, nodeReward);
                    emit NodeReward(user, nodeReward);
                }
                userNodeIndex[user] = accNode;
            }
        }
